describe("npmFetch", () => {
  const fetchMock = vi.fn<typeof fetch>();

  beforeEach(() => {
    vi.useFakeTimers();
    vi.stubGlobal("fetch", fetchMock);
  });

  afterEach(() => {
    vi.useRealTimers();
    vi.unstubAllGlobals();
    fetchMock.mockReset();
  });

  it("returns the first response when it isn't a 429", async () => {
    fetchMock.mockResolvedValueOnce(response(200));
    const res = await npmFetch("https://registry.npmjs.org/x");
    expect(res.status).toBe(200);
    expect(fetchMock).toHaveBeenCalledTimes(1);
  });

  it("doesn't retry other errors", async () => {
    fetchMock.mockResolvedValueOnce(response(500));
    const res = await npmFetch("https://registry.npmjs.org/x");
    expect(res.status).toBe(500);
    expect(fetchMock).toHaveBeenCalledTimes(1);
  });

  it("retries a 429 and returns the later success", async () => {
    fetchMock
      .mockResolvedValueOnce(response(429))
      .mockResolvedValueOnce(response(429))
      .mockResolvedValueOnce(response(200));
    const pending = npmFetch("https://registry.npmjs.org/x");
    await vi.runAllTimersAsync();
    expect((await pending).status).toBe(200);
    expect(fetchMock).toHaveBeenCalledTimes(3);
  });

  it("waits as long as Retry-After asks", async () => {
    fetchMock
      .mockResolvedValueOnce(response(429, { "retry-after": "5" }))
      .mockResolvedValueOnce(response(200));
    const pending = npmFetch("https://registry.npmjs.org/x");
    await vi.advanceTimersByTimeAsync(4_999);
    expect(fetchMock).toHaveBeenCalledTimes(1);
    await vi.advanceTimersByTimeAsync(1);
    expect((await pending).status).toBe(200);
  });

  it("gives up after 4 tries and returns the last 429", async () => {
    fetchMock.mockResolvedValue(response(429));
    const pending = npmFetch("https://registry.npmjs.org/x");
    await vi.runAllTimersAsync();
    expect((await pending).status).toBe(429);
    expect(fetchMock).toHaveBeenCalledTimes(4);
  });
});

const MAX_TRIES = 4;

// The npm search endpoint returns 429 when an eval batch calls it too fast.
// Retry those, waiting as long as Retry-After says, or 1s, 2s, 4s without it.
export async function npmFetch(url: string): Promise<Response> {
  for (let attempt = 1; ; attempt++) {
    const res = await fetch(url);
    if (res.status !== 429 || attempt === MAX_TRIES) return res;
    const retryAfter = Number(res.headers.get("retry-after"));
    const waitMs = retryAfter > 0 ? retryAfter * 1000 : 2 ** (attempt - 1) * 1000;
    await new Promise((resolve) => setTimeout(resolve, waitMs));
  }
}

